SELECT id, uuid, company_name, company_abbr, contact_name, contact_phone, license_num, status, create_time FROM companies WHERE is_del = false
AND (company_name LIKE CONCAT('%', #{keyword}, '%') OR company_abbr LIKE CONCAT('%', #{keyword}, '%') OR contact_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY create_time DESC LIMIT #{size} OFFSET #{offset}
